INSERT INTO recommendations(code, title, summary, instructions_json, duration_minutes, caution_text, active) VALUES
('ANKLE_STABILITY_BASIC', '기본 발목 안정화 운동', '균형 유지와 발목 주변 근육 사용을 돕는 기초 운동입니다.', '["안정된 지지대 옆에 섭니다.","한 발로 서서 20초간 균형을 유지합니다.","양쪽을 번갈아 3회 반복합니다."]', 10, '통증이나 심한 불편감이 생기면 중단하고 전문가와 상담하세요.', TRUE),
('BALANCED_FOOT_LOADING', '균형 잡힌 발 디딤 연습', '발 안쪽과 바깥쪽에 고르게 힘을 싣는 감각을 연습합니다.', '["양발을 골반 너비로 둡니다.","발바닥 세 지점을 바닥에 고르게 댑니다.","천천히 체중을 이동하며 10회 반복합니다."]', 8, '통증이 있거나 균형을 유지하기 어렵다면 지지대를 사용하세요.', TRUE),
('REMEASURE_GUIDE', '같은 조건에서 재측정', '데이터 품질을 확인하기 위해 같은 환경에서 다시 측정해 보세요.', '["기기 연결과 인솔 위치를 확인합니다.","평평한 바닥에서 같은 속도로 걷습니다.","측정 중 연결 경고를 확인합니다."]', 5, '이 안내는 의료 진단이 아닙니다.', TRUE);
